*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}body{background:#10151c;color:#f5f6fa}button,input{font:inherit}button{border:0;border-radius:14px;min-height:40px;padding:0 15px;background:#ffffff18;color:inherit;cursor:pointer}button:disabled{opacity:.4}button.primary{background:#e8f2fa;color:#132535}input{min-width:0;background:#ffffff12;color:inherit;border:1px solid #ffffff20;border-radius:14px;padding:10px 12px;outline:none}header{height:55px;display:flex;align-items:center;justify-content:space-between;padding:0 19px}h1{font-size:19px;font-weight:650;letter-spacing:-.5px;margin:0}small{font-size:11px;color:#a8b4c4}footer{position:absolute;bottom:0;left:0;right:0;padding:9px 14px 12px;background:linear-gradient(transparent,#10151cf5 18%)}.entry{display:flex;gap:7px}.entry input{flex:1;font-size:13px}.status{height:20px;font-size:11px;color:#bdc9d7;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding:4px 1px}#save{font-size:12px;min-height:32px;padding:0 10px}button:focus-visible,input:focus-visible{outline:2px solid #91d7ee;outline-offset:2px}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
body{background:#111c25}header{position:absolute;z-index:1;top:0;width:100%}header small{display:block;margin-top:3px}canvas{width:100%;height:100%;image-rendering:pixelated}#panel{position:absolute;bottom:10px;left:14px;right:14px;background:#172632f5;border:1px solid #ffffff1a;border-radius:18px;padding:10px 12px}.filter{display:flex;align-items:center;gap:7px;margin-bottom:7px}.filter select{font:inherit;font-size:12px;min-width:0;max-width:150px;width:130px;height:30px;padding:4px 6px;border:0;border-radius:8px;background:#ffffff10;color:#e7eef4}.filter option{background:#172632;color:#e7eef4}.filter button{font-size:11px;min-height:30px;padding:0 8px}#updated{font-size:10px;white-space:nowrap;margin-left:auto}#task{font-size:15px;margin-bottom:4px;white-space:nowrap;text-overflow:ellipsis;overflow:hidden}#detail{font-size:12px;color:#b8c8d6;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;height:18px}.actions{display:flex;gap:6px;align-items:center;margin-top:8px}.actions button{min-height:34px;padding:0 11px;font-size:12px}#page{font-size:11px;color:#91acbd;min-width:32px;text-align:center}#new{margin-left:auto}.feedback-row{display:flex;align-items:center;gap:5px;min-height:16px;margin-top:3px}#feedback{font-size:10px;color:#e8bd8b;flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}#retry-save{min-height:20px;padding:0 6px;font-size:10px}[hidden]{display:none!important}select:focus-visible{outline:2px solid #91d7ee;outline-offset:2px}

/* Room owns its header and keeps task tools on a separate, reversible view. */
header{height:58px;padding:0 10px;gap:6px;pointer-events:auto}header>div{flex:1;min-width:0}header h1{font-size:17px}header #back{min-width:70px;min-height:48px;padding:0 3px;background:none;color:var(--accent,#b7d9d0);font-size:13px}header #view,header #refresh{font-size:12px;padding:0 10px;min-height:34px}header small{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:10px}body[data-view=room] #panel,body[data-view=room] #refresh,body[data-view=tasks] #living{display:none}#living{position:absolute;bottom:18px;left:24px;right:24px;text-align:center}.living-caption span{display:block;font-size:17px;letter-spacing:.5px;margin-bottom:7px}.living-caption small{display:block;color:#94b3bd}.living-controls{display:flex;justify-content:center;gap:12px;margin:15px 0 8px}.living-controls button{background:#d3e0d914;border:1px solid #bfd7cf30;font-size:12px;min-height:36px}#demo-label{color:#809aa7;font-size:10px}body[data-view=room] canvas{height:88%;margin-top:4%}#back:focus-visible{outline:none}body[data-view=tasks] canvas{opacity:.8}

