'use strict';
AtomApp.deferReady();
let alive=true,state=null,timer,frame,ageTimer,pending=new Map(),serial=0,error='',storageError='',blocked=false,last=0,loading=false,canSave=false,saveChain=Promise.resolve(),selection={computer:'',task:''};
const $=s=>document.querySelector(s),c=$('#room'),g=c.getContext('2d'),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let roomView=true,present=true,manual=false,tilt=0,swayUntil=0,unsubscribe,animationAllowed=true;
const quiet=()=>reduced||!animationAllowed;
const labels={queued:'等待接收',running:'正在工作',waiting_approval:'需要你确认',completed:'作品已完成',failed:'需要检查',cancelled:'已取消',interrupted:'已中断',expired:'任务已失效'};
function request(type,data){return new Promise((resolve,reject)=>{if(!alive)return reject(Error('应用已退出'));let id='room-'+(++serial),timeout=setTimeout(()=>{pending.delete(id);reject(Error('连接超时，请刷新重试'))},12000);pending.set(id,{resolve,reject,timeout});parent.postMessage({type,id,...data},'*')})}
addEventListener('message',e=>{if(e.source!==parent)return;if(e.data?.type==='atom:input-settings'){animationAllowed=e.data.motion!==false;return}let p=pending.get(e.data?.id);if(!p)return;clearTimeout(p.timeout);pending.delete(e.data.id);e.data.error?p.reject(Error(e.data.error)):p.resolve(e.data.result||{})});
function tasks(){return(state?.tasks||[]).filter(t=>!selection.computer||t.computer_id===selection.computer)}
function chosen(){const list=tasks();return list.find(t=>t.id===selection.task)||list.find(t=>t.status==='waiting_approval')||list.find(t=>t.status==='running')||list.find(t=>t.status==='queued')||list[0]}
function stale(){const t=chosen(),host=(state?.paired||[]).find(p=>p.client_id===t?.computer_id);return !!error||!!state?.connection_error||!!(t&&(!host||host.online!==true))}
function age(){const t=chosen(),n=t?.updated_at,stamp=typeof n==='number'?(n>1e12?n:n*1000):Date.parse(n),seconds=Math.max(0,Math.floor((Date.now()-stamp)/1000));$('#updated').textContent=Number.isFinite(seconds)?(seconds<60?seconds+' 秒前回传':seconds<3600?Math.floor(seconds/60)+' 分钟前回传':Math.floor(seconds/3600)+' 小时前回传'):''}
function render(){if(!alive)return;const list=tasks(),t=chosen(),index=list.indexOf(t),hosts=state?.paired||[],online=hosts.filter(p=>p.online).length,isStale=stale(),studio=String(t?.id||'').startsWith('studio-');
 $('#connection').textContent=error||state?.connection_error?'连接中断 · 上次已知状态':!state?'正在同步电脑状态…':!state.configured?'尚未连接':online+' 台电脑在线 · 真实任务';
 $('#task').textContent=t?(isStale?'上次状态 · ':'')+(labels[t.status]||t.status):selection.computer?'这台电脑暂时没有任务':'工作室暂时安静';
 $('#detail').textContent=t?(t.prompt||'电脑任务'):(online?'准备好新想法了吗？发起一个任务吧。':'连接电脑后，这里会呈现真实工作状态。');$('#detail').title=t?.prompt||'';
 const select=$('#computer'),value=selection.computer;select.replaceChildren();const all=document.createElement('option');all.value='';all.textContent='所有电脑';select.append(all);hosts.forEach(h=>{const option=document.createElement('option');option.value=h.client_id;option.textContent=(h.name||'我的电脑')+(h.online?'':' · 离线');select.append(option)});if(value&&!hosts.some(h=>h.client_id===value)){const missing=document.createElement('option');missing.value=value;missing.textContent='已关注电脑 · 暂不可用';select.append(missing)}select.value=value;select.disabled=!canSave;
 $('#page').textContent=list.length?(index+1)+' / '+list.length:'0 / 0';$('#prev').disabled=index<=0;$('#next').disabled=index<0||index>=list.length-1;$('#follow').textContent=selection.task?'取消关注':'关注此任务';$('#follow').disabled=!canSave||!t;
 $('#open').textContent=studio?'请在电脑端查看':t?'查看任务':'连接电脑';$('#open').disabled=studio;$('#new').textContent=state?.configured?'新任务':'连接电脑';
 $('#feedback').textContent=storageError||error||state?.connection_error||(isStale?'电脑已离线，恢复连接后再确认进度。':studio?'电脑端创作任务，详情与确认请在电脑工作台操作。':'');$('#retry-save').hidden=!storageError;age();draw(performance.now(),true)}
async function load(){try{const saved=await AtomApp.load({computer:'',task:''});if(!alive)return;if(!saved||typeof saved.computer!=='string'||typeof saved.task!=='string')throw Error('关注偏好格式异常');selection={computer:saved.computer.slice(0,128),task:saved.task.slice(0,128)};canSave=true;storageError=''}catch(e){canSave=false;storageError='关注偏好读取失败，重试前不会覆盖原记录'}render()}
function persist(){if(!canSave)return Promise.resolve(false);const snapshot={...selection};saveChain=saveChain.catch(()=>{}).then(()=>AtomApp.save(snapshot)).then(()=>{storageError='';render();return true}).catch(()=>{storageError='关注偏好未保存，点击重试';render();return false});return saveChain}
function poly(points,color){g.fillStyle=color;g.beginPath();points.forEach(([x,y],i)=>i?g.lineTo(x,y):g.moveTo(x,y));g.closePath();g.fill()}function rect(x,y,w,h,color){g.fillStyle=color;g.fillRect(Math.round(x),Math.round(y),w,h)}
function draw(now,force=false){if(!alive)return;if(force||now-last>=(quiet()?1000:100)){last=now;g.save();g.translate(Math.max(-3,Math.min(3,tilt/8)),0);g.fillStyle='#111c25';g.fillRect(0,0,240,180);poly([[25,78],[120,31],[216,78],[120,127]],'#27414a');poly([[25,78],[25,101],[120,150],[120,127]],'#1b303b');poly([[120,127],[216,78],[216,101],[120,150]],'#223a44');for(let i=0;i<7;i++){g.strokeStyle='#ffffff08';g.beginPath();g.moveTo(25+i*14,78-i*7);g.lineTo(120+i*14,127-i*7);g.stroke()}poly([[30,76],[30,44],[119,0],[119,32]],'#203844');poly([[119,32],[119,0],[210,44],[210,76]],'#294450');rect(145,23,34,26,'#101f2c');rect(148,26,28,20,'#345b70');rect(161,26,2,20,'#819b9c');rect(148,35,28,2,'#819b9c');rect(151,28,3,3,'#d2d3aa');rect(172,39,2,2,'#e4d3a2');poly([[66,69],[120,43],[167,67],[112,94]],'#bb956c');poly([[66,69],[66,74],[112,99],[112,94]],'#886b53');poly([[112,94],[167,67],[167,72],[112,99]],'#9d7f5f');rect(76,76,5,21,'#795c47');rect(153,73,5,20,'#795c47');rect(113,48,23,17,'#101b27');let t=chosen(),running=!stale()&&t?.status==='running',approval=!stale()&&t?.status==='waiting_approval',done=!stale()&&t?.status==='completed';rect(116,51,17,11,approval?'#dfb77b':done?'#8bd2b3':running?'#8acbd3':'#3c6173');if(running){let k=quiet()?0:Math.floor(now/200)%4;for(let i=0;i<3;i++)rect(118,54+i*3,4+((k+i)%4)*2,1,'#294556')}rect(124,65,3,5,'#4b6470');rect(117,69,16,2,'#324b58');let bob=running&&!quiet()?Math.floor(now/400)%2:0;rect(93,66+bob,15,13,'#d9d4b4');rect(96,79+bob,10,12,'#749b9b');rect(95,69+bob,3,3,'#233a45');rect(103,69+bob,3,3,'#233a45');rect(97,91,3,6,'#385262');rect(104,91,3,6,'#385262');rect(90,80+bob,5,3,'#d9d4b4');rect(106,80+bob,8,3,'#d9d4b4');rect(183,74,12,13,'#b49776');rect(187,63,4,15,'#629a88');rect(181,64,7,5,'#88b39a');rect(190,60,7,5,'#8fbca3');if(approval){rect(94,52,13,10,'#e5be86');rect(99,54,3,4,'#4b443d');rect(99,59,3,1,'#4b443d')}if(done){rect(149,54,7,5,'#e9d9ac');rect(151,51,3,3,'#f2eacb')}if(!present){g.fillStyle='#07122299';g.fillRect(-4,0,248,180);rect(95,72,11,1,'#c3bda6')}if(now<swayUntil&&!quiet()){g.fillStyle='#d7e7b7';g.fillRect(176+Math.sin(now/180)*5,57,2,2)}g.restore()}if(!force)frame=setTimeout(()=>draw(performance.now()),quiet()?1000:100)}
async function refresh(){if(loading||!alive)return;clearTimeout(timer);loading=true;$('#refresh').disabled=true;try{const result=await request('atom:task-state');if(alive){state=result;error='';blocked=false}}catch(e){error=e.message;if(/允许|权限/.test(error))blocked=true}finally{loading=false;if(alive){$('#refresh').disabled=false;render();if(!blocked)timer=setTimeout(refresh,5000)}}}
$('#refresh').onclick=()=>{blocked=false;if(!canSave)load();refresh()};$('#retry-save').onclick=()=>canSave?persist():load();
$('#computer').onchange=e=>{selection={computer:e.target.value,task:''};persist();render()};
function move(delta){const list=tasks(),index=list.indexOf(chosen()),next=list[index+delta];if(!next)return;selection.task=next.id;persist();render()}
$('#prev').onclick=()=>move(-1);$('#next').onclick=()=>move(1);$('#follow').onclick=()=>{const t=chosen();selection.task=selection.task?'':t?.id||'';persist();render()};
async function openComputer(task){try{await request('atom:agent-studio',{action:'open-computer',data:task?{task_id:task.id}:{}})}catch(e){if(alive){error=e.message;render()}}}
$('#open').onclick=()=>openComputer(chosen());$('#new').onclick=()=>openComputer(null);
function setRoomView(value){roomView=value;document.body.dataset.view=value?'room':'tasks';$('#view').textContent=value?'任务':'小屋';$('#back').textContent=value?'‹ 桌面':'‹ 小屋';}
function updateMood(){ $('#presence-demo').textContent=present?'体验离开':'体验回来';$('#mood').textContent=present?'灯亮着，想法也会慢慢长大。':'小屋安静下来了，等你回来。';draw(performance.now(),true); }
$('#view').onclick=()=>setRoomView(!roomView);
function goBack(){if(!roomView)setRoomView(true);else AtomApp.home()}
$('#back').onclick=goBack;
if(AtomApp.navigation)AtomApp.navigation.setBackHandler(goBack);
$('#presence-demo').onclick=()=>{manual=true;present=!present;$('#presence-demo').textContent=present?'体验离开':'体验回来';$('#sensor-status').textContent='手动演示 · 不代表真实传感器状态';updateMood()};
$('#sway').onclick=()=>{manual=true;swayUntil=performance.now()+1600;$('#sensor-status').textContent='手动演示 · 摇动窗边的光点';};
if(AtomApp.sensors?.subscribe)unsubscribe=AtomApp.sensors.subscribe(sample=>{
 if(!alive)return;
 if(sample.source!=='device'){if(!manual)$('#sensor-status').textContent='传感器未连接 · 手动陪伴';tilt=0;return;}
 manual=false;
 if(sample.available?.presence&&typeof sample.presence?.present==='boolean')present=sample.presence.present;
 tilt=sample.available?.motion&&Number.isFinite(sample.motion?.roll)?sample.motion.roll:0;
 if(sample.available?.motion&&sample.motion?.moving)swayUntil=performance.now()+800;
 $('#sensor-status').textContent='实时感知 · '+[sample.available?.presence?'人体存在':'',sample.available?.motion?'机身运动':''].filter(Boolean).join(' / ');
 updateMood();
});
render();frame=setTimeout(()=>draw(performance.now()),100);load().finally(()=>{if(alive){AtomApp.ready();refresh()}});ageTimer=setInterval(()=>{if(alive)age()},1000);
AtomApp.onSuspend(()=>{alive=false;unsubscribe?.();clearTimeout(frame);clearTimeout(timer);clearInterval(ageTimer);for(const p of pending.values()){clearTimeout(p.timeout);p.reject(Error('应用已退出'))}pending.clear()});
